changeSet.sql:
create table data.futures_metrics_groups (
  id       int4 not null,
  grp_code text not null,
  grp_name text not null,
  constraint pk_futures_metrics_groups primary key (id),
  constraint uk_futures_metrics_groups_code unique (grp_code)
);
insert into data.futures_metrics_groups(id, grp_code, grp_name) values (1, 'price down oi down', 'price down, oi down');
insert into data.futures_metrics_groups(id, grp_code, grp_name) values (2, 'price down oi up',   'price down, oi up');
insert into data.futures_metrics_groups(id, grp_code, grp_name) values (3, 'price up oi down',   'price up, oi down');
insert into data.futures_metrics_groups(id, grp_code, grp_name) values (4, 'price up oi up',     'price up, oi up');
insert into data.futures_metrics_groups(id, grp_code, grp_name) values (5, 'flat',               'flat');

insert into data.futures_metrics(metric_name, metric_table)
values ('compare price and oi', 'futures_data_price_oi_metrics');

insert into data.futures_metrics_meta(
  execute_every_mins, id_futures_metrics, filter_window_min, compare_interval_min,
  filter_total_oi, price_change_threshold, oi_change_threshold
) values (5, 1, 120, 60, 0.005, 0.001, 0.001);

create trigger trg_dict_changed_futures_metrics
after insert or update or delete on data.futures_metrics
for each statement execute function data.fn_dict_changed_notify();

create trigger trg_dict_changed_futures_metrics_meta
after insert or update or delete on data.futures_metrics_meta
for each statement execute function data.fn_dict_changed_notify();
